#include <string.h>

#define MAX 100

typedef struct {
    char name[32];
    char phone[20];
} Contact;

int add_one(Contact book[], int n, char *name, char *phone) {
    if (n >= MAX) {
        printf("记满了喵\n");
        return n;
    }
    strcpy(book[n].name, name);
    strcpy(book[n].phone, phone);
    return n + 1;
}

void list_all(Contact book[], int n) {
    if (n == 0) {
        printf("还一条都没有喵\n");
        return;
    }
    for (int i = 0; i < n; i++) {
        printf("%d. %s %s\n", i + 1, book[i].name, book[i].phone);
    }
}

int save_all(Contact book[], int n, char *path) {
    FILE *fp = fopen(path, "w");
    if (fp == NULL) {
        printf("打不开喵\n");
        return 0;
    }
    for (int i = 0; i < n; i++) {
        fprintf(fp, "%s %s\n", book[i].name, book[i].phone);
    }
    fclose(fp);
    printf("存好了喵\n");
    return 1;
}

int load_all(Contact book[], char *path) {
    FILE *fp = fopen(path, "r");
    int n = 0;
    if (fp == NULL) {
        printf("还没有册子喵\n");
        return 0;
    }
    while (n < MAX && fscanf(fp, "%31s %19s", book[n].name, book[n].phone) == 2) {
        n = n + 1;
    }
    fclose(fp);
    return n;
}

int main(void) {
    Contact book[MAX];
    int n = 0;

    n = add_one(book, n, "小橘", "13800000001");
    n = add_one(book, n, "狸花", "13700000003");
    n = add_one(book, n, "奶牛", "13500000005");

    printf("存之前一共 %d 条\n", n);
    list_all(book, n);
    save_all(book, n, "book.txt");

    Contact again[MAX];
    int m = load_all(again, "book.txt");
    printf("读回来一共 %d 条\n", m);
    list_all(again, m);
    save_all(again, m, "book2.txt");
    return 0;
}

items.explanation:
存和读这一对是这一课最实用的一段喵 —— **写完它，小册子就真的能留下来了**。

**① 存：开、写、关。**

```c
FILE *fp = fopen(path, "w");
if (fp == NULL) {
    ...
    return 0;
}
for (int i = 0; i < n; i++) {
    fprintf(fp, "%s %s\n", book[i].name, book[i].phone);
}
fclose(fp);
```

三件事一件都不能少：**开门**（`fopen` 报的那个 `"w"` 是「要写，而且从头写起」）、**一条一条写**、**关门**（`fclose`）。少关一次门，写出去的东西可能还堵在半路上没落到盘上。前面那一道 `fp == NULL` 是保命的：门没开成还硬往里写，程序当场就倒。

**② 读：开门、一条条念、关门。**

```c
while (n < MAX && fscanf(fp, "%31s %19s", book[n].name, book[n].phone) == 2) {
    n = n + 1;
}
```

这一行是整道题的核心，三个要点拆开看：

- **`== 2` 是「这一趟读满两格了吗」**。名字和号码是两样东西，读满两样它才交 2；读不动就交别的数，绕圈当场收手。**交回来的数就是它这一趟干成了几样**。
- **`n < MAX` 挡在前面**：册子最多装 100 条，读满 100 条就收手，别硬往里塞第 101 条。
- **`book[n].name` 前面没有 `&`**：那两格本身就是碗，直接报名字就行。

**③ 为什么每一条正好落在第 `n` 格？** 因为每读一条就 `n = n + 1`，所以「已经读进来几条」和「下一条该放哪一格」永远是同一个数。**读进来的条数不是本喵数出来的，是这一招交回来的。**

**④ 存和读必须是同一套规矩。** 存的是「名字、空格、号码」，读的时候就得按「不要空格的一串、再不要空格的一串」去念 —— 中间那个空格**它自己会跳过**，所以两边就对上了。要是存的时候用逗号、读的时候找空格，那就是两条规矩，一条都读不回来（这一课那道改错题就是这个坑）。

**⑤ 两个文件都要自己开、自己关。** `main` 里存了一次、读了一次、又存了一次，前后开了三回门 —— **每一回都得配一个 `fclose`**。第一次存完那本在内存里，读回来的是另一本，两边各走各的，所以印出来的一模一样。

